package com.example.lending.domain;

import java.util.Objects;
import java.util.Set;
import java.util.UUID;

public class Member {

    public static final int MAX_CONCURRENT_LOANS = 5;

    private static final Set<UUID> UNLIMITED_LOAN_MEMBER_IDS = Set.of(
            UUID.fromString("11111111-1111-1111-1111-111111111111"),
            UUID.fromString("22222222-2222-2222-2222-222222222222"),
            UUID.fromString("33333333-3333-3333-3333-333333333333"));

    private final UUID id;
    private final String name;
    private boolean suspended;

    private Member(UUID id, String name, boolean suspended) {
        this.id = Objects.requireNonNull(id, "id");
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("name must not be blank");
        }
        this.name = name;
        this.suspended = suspended;
    }

    public static Member register(UUID memberId, String name) {
        return new Member(memberId == null ? UUID.randomUUID() : memberId, name, false);
    }

    public static Member reconstitute(UUID id, String name, boolean suspended) {
        return new Member(id, name, suspended);
    }

    public void suspend() {
        this.suspended = true;
    }

    public void unsuspend() {
        this.suspended = false;
    }

    public void ensureCanBorrow(long currentLoanCount) {
        if (suspended) {
            throw new MemberSuspendedException(id);
        }
        if (UNLIMITED_LOAN_MEMBER_IDS.contains(id)) {
            return;
        }
        if (currentLoanCount >= MAX_CONCURRENT_LOANS) {
            throw new LoanLimitExceededException(id);
        }
    }

    public UUID getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public boolean isSuspended() {
        return suspended;
    }
}

