import com.example.lending.domain.Member;
import com.example.lending.domain.MemberNotFoundException;
import com.example.lending.domain.Reservation;
import com.example.lending.domain.ReservationQueue;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional
public class PlaceReservationService implements PlaceReservationUseCase {

    private final LoadBookPort loadBookPort;
    private final LoadMemberPort loadMemberPort;
    private final LoadReservationPort loadReservationPort;
    private final SaveReservationPort saveReservationPort;

    public PlaceReservationService(LoadBookPort loadBookPort, LoadMemberPort loadMemberPort,
                                   LoadReservationPort loadReservationPort, SaveReservationPort saveReservationPort) {
        this.loadBookPort = loadBookPort;
        this.loadMemberPort = loadMemberPort;
        this.loadReservationPort = loadReservationPort;
        this.saveReservationPort = saveReservationPort;
    }

    @Override
    public QueuedReservation placeReservation(PlaceReservationCommand command) {
        Book book = loadBookPort.loadBook(command.bookId())
                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
        Member member = loadMemberPort.loadMember(command.memberId())
                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
        book.ensureReservable();
        ReservationQueue queue = new ReservationQueue(book.getId(),
                loadReservationPort.loadWaitingReservations(book.getId()));
        queue.ensureNotReservedBy(member.getId());
        Reservation reservation = Reservation.place(book.getId(), member.getId());
        saveReservationPort.saveReservation(reservation);
        return new QueuedReservation(reservation, queue.nextPosition());
    }
}
